def hdr(p,n):
    for h in p.get('headers',[]):
        if h['name'].lower()==n: return h['value']
    return ''
def dec(b):
    try: return base64.urlsafe_b64decode(b.encode('ascii')+b'==').decode('utf-8','ignore')
    except Exception: return b
def get_text(p):
    out=''
    if p.get('mimeType','').startswith('text/plain'):
        b=p.get('body',{}).get('data')
        if b: out+=dec(b)
    for part in p.get('parts',[]):
        out+=get_text(part)
    return out
